z-Strings */resource 'STR#' (kDebugBuzzStrings,#if qNames	"DebugBuzzStrings",#endif	purgeable) {	 {			/* [1] */	"Do First Click For This Window";		/* [2] */	"Don't Do First Click For This Window";		/* [3] */	"Set system to right justification";		/* [4] */	"Set system to left justification";		/* [5] */	"Continue performance monitor";		/* [6] */	"Pause performance monitor"	}};/* Debug Error-Strings */resource 'STR#' (kDebugErrorStrings,#if qNames	"kDebugErrorStrings",#endif	purgeable) {	 {	"Level 7 Interupt";	"Bus error:  Invalid memory reference";	"Address error:  Word or long-word reference made to an odd address";	"Illegal instruction:  The processor received an instruction it didn't recognize.";	"Zero divide:  Signed Divide (DIVS) or Unsigned Divide (DIVU) instruction with a divisor of 0 was executed.";	"Check exception:  Check Register Against Bounds (CHK) instruction was executed and failed.  Pascal 'value out of range' errors are usually reported in this way.";	"TrapV exception:  Trap On Overflow (TRAPV) instruction was executed and failed.";	"Privilege violation:  Macintosh always runs in supervisor mode; perhaps an erroneous Return From Execution (RTE) instruction was executed.";	"Trace exception:  The trace bit in the status register is set.";	"Line 1010 exception:  The 1010 trap dispatcher has failed.";	"Line 1111 exception:  Unimplemented instruction";	"Miscellaneous exception:  All other processor exceptions";	"Unimplemented core routine:  An unimplemented trap number was encountered.";	"Spurious interrupt:  The interrupt vector table entry for a particular level of interrupt is NULL; usually occurs with level 4, 5, 6, or 7 interrupts.";	"I/O system error:  The File Manager is attempting to dequeue an entry from an I/O request queue that has a bad queue type field.";	"Segment Loader error:  A GetResource call to read a segment into memory failed.";	"Floating point error:  The halt bit in the floating-point environment word was set.";	"Can't load package 0:  A GetResource call to read a package into memory failed.";	"Can't load package 1:  A GetResource call to read a package into memory failed.";	"Can't load Disk Initialization package:  A GetResource call to read a package into memory failed.";	"Can't load Standard File package:  A GetResource call to read a package into memory failed.";	"Can't load Floating Point package:  A GetResource call to read a package into memory failed.";	"Can't load Trancendentals package:  A GetResource call to read a package into memory failed.";	"Can't load International Utilities package:  A GetResource call to read a package into memory failed.";	"Can't load Binary-Decimal package:  A GetResource call to read a package into memory failed.";	"Can't allocate requested memory block in the heap";	"Segment Loader error:  A GetResource call to read 'CODE' resource 0 into memory failed; usually indicates a nonexecutable file.";	"File map destroyed:  A logical block number was found that's greater than the number of the last logical block on the volume or less than the logical block number of the first allocation block on the volume.";	"Stack overflow error:  The stack has expanded into the heap.";	"Negative ZcbFree value (Memory manager error.  See TN-151)";	"The file named 'Finder' can't be found on the disk.";	"ShutDown Alert";	"Unserviceable slot interrupt";	"Bad opcode given to SANE package 4";	"Menu Manager tried to access a menu that's been purged.";	"Menu bar not found";	"Menu find error";	"Can't mount system startup volume.  The system couldn't read the system resource file into memory.";	"'Sorry, a system error occurred':  Default alert message";	"Mem Mgr Err";	"Unlisted error.  See IM III-205"	 }};